export const INSTALL_BAT = "@echo off\nsetlocal enabledelayedexpansion\n\nset \"MQ=%APPDATA%\\MetaQuotes\\Terminal\"\nset \"EA=MT4ReportExporter.mq4\"\n\necho ============================================\necho   MT4ReportExporter Setup\necho ============================================\necho.\n\nREM --- Check EA file exists ---\nif not exist \"%~dp0%EA%\" (\n    echo ERROR: %EA% not found.\n    echo Place install.bat and MT4ReportExporter.mq4\n    echo in the same folder, then run again.\n    echo.\n    pause & exit /b 1\n)\n\nREM --- Check MetaQuotes folder exists ---\nif not exist \"%MQ%\" (\n    echo ERROR: MT4 not found.\n    echo Launch MT4 once, then run this script again.\n    echo.\n    pause & exit /b 1\n)\n\nREM --- Pre-create MT4Export output folder ---\nmkdir \"%USERPROFILE%\\MT4Export\" 2>nul\n\nREM --- Get actual Desktop path (handles OneDrive redirection) ---\nset \"DESKTOP=\"\nfor /f \"tokens=2,*\" %%A in ('reg query \"HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\" /v Desktop 2^>nul') do set \"DESKTOP=%%B\"\nif not defined DESKTOP set \"DESKTOP=%USERPROFILE%\\Desktop\"\nset \"BAT=!DESKTOP!\\MT4_Exporter.bat\"\n\nREM --- Initialize launcher batch (profile-based launch) ---\n(\n    echo @echo off\n) > \"!BAT!\"\n\nset COUNT=0\n\nfor /d %%D in (\"%MQ%\\*\") do (\n    if exist \"%%D\\origin.txt\" (\n\n        REM --- Read install path from origin.txt (UTF-16), append terminal.exe if needed ---\n        set \"EXE=\"\n        for /f \"tokens=* delims=\" %%L in ('type \"%%D\\origin.txt\"') do (\n            if not defined EXE set \"EXE=%%L\"\n        )\n        if defined EXE if exist \"!EXE!\\\" set \"EXE=!EXE!\\terminal.exe\"\n\n        if defined EXE (\n            if exist \"!EXE!\" (\n\n                REM --- Copy EA to Experts folder ---\n                mkdir \"%%D\\MQL4\" 2>nul\n                mkdir \"%%D\\MQL4\\Experts\" 2>nul\n                copy /y \"%~dp0%EA%\" \"%%D\\MQL4\\Experts\\%EA%\" >nul 2>&1\n\n                REM --- .ex4 is auto-compiled by MT4 on first launch ---\n                if exist \"%%D\\MQL4\\Experts\\%EA%\" (\n                    echo      EA copy  : OK\n                ) else (\n                    echo      EA copy  : FAILED\n                )\n\n                REM --- Create MT4Exporter profile directory ---\n                mkdir \"%%D\\profiles\" 2>nul\n                mkdir \"%%D\\profiles\\charts\" 2>nul\n                mkdir \"%%D\\profiles\\charts\\MT4Exporter\" 2>nul\n\n                REM --- Copy charts from any existing profile so /expert: has a chart to attach to ---\n                set \"COPIED=0\"\n                for /d %%P in (\"%%D\\profiles\\charts\\*\") do (\n                    if /i not \"%%~nxP\"==\"MT4Exporter\" if \"!COPIED!\"==\"0\" (\n                        if exist \"%%P\\*.chr\" (\n                            copy /y \"%%P\\*.chr\" \"%%D\\profiles\\charts\\MT4Exporter\\\" >nul 2>&1\n                            set \"COPIED=1\"\n                        )\n                    )\n                )\n\n                REM --- Add to launcher bat with profile ---\n                (\n                    echo start \"\" \"!EXE!\" /profile:MT4Exporter\n                ) >> \"!BAT!\"\n\n                set /a COUNT+=1\n                echo [!COUNT!] !EXE!\n                echo.\n            )\n        )\n    )\n)\n\nif !COUNT! gtr 0 (\n    echo ============================================\n    echo   Launching MT4 for one-time profile setup\n    echo ============================================\n    echo.\n\n    REM --- Close any running MT4 before setup launch ---\n    taskkill /im terminal.exe 2>nul\n    timeout /t 5 /nobreak >nul\n\n    for /d %%D in (\"%MQ%\\*\") do (\n        if exist \"%%D\\origin.txt\" (\n            set \"EXE=\"\n            for /f \"tokens=* delims=\" %%L in ('type \"%%D\\origin.txt\"') do (\n                if not defined EXE set \"EXE=%%L\"\n            )\n            if defined EXE if exist \"!EXE!\\\" set \"EXE=!EXE!\\terminal.exe\"\n            if defined EXE if exist \"!EXE!\" (\n                start \"\" \"!EXE!\" /profile:MT4Exporter /expert:MT4ReportExporter\n            )\n        )\n    )\n\n    echo For EACH MT4 window that opens:\n    echo   1. Wait for MT4 to fully load\n    echo   2. Drag MT4ReportExporter onto any chart\n    echo   3. Click OK in the EA settings dialog\n    echo   4. File -^> Profiles -^> Save As... -^> type: MT4Exporter -^> OK\n    echo   5. Close MT4 ^(File -^> Exit^)\n    echo.\n    echo After doing this for ALL MT4 windows, setup is complete.\n    echo Use MT4_Exporter.bat on Desktop for all future launches.\n    echo ^(EA loads automatically via profile on every launch^)\n)\n\necho ============================================\nif !COUNT!==0 (\n    echo No MT4 installation found.\n    echo Launch MT4 once, then run this script again.\n) else (\n    echo Setup complete ^(!COUNT! instance^(s^)^)\n    echo Launcher: !BAT!\n)\necho ============================================\necho.\npause\n"
export const MQ4_CONTENT = "//+------------------------------------------------------------------+\n//|  MT4ReportExporter.mq4                                           |\n//|  取引履歴を JSON に自動エクスポートする EA                        |\n//|                                                                  |\n//|  【特徴】                                                        |\n//|  ・自動売買（Auto Trading）が OFF でも動作します                  |\n//|  ・注文・決済などの売買操作は一切行いません                      |\n//|  ・ファイル書き出しのみ実行します                                |\n//|  ・ブラウザの「更新」ボタンで即時エクスポートに対応              |\n//|                                                                  |\n//|  【設置方法】                                                    |\n//|  1. MQL4\\Experts\\ フォルダにコピー                               |\n//|  2. MT4_Exporter.bat で MT4 を起動                               |\n//|  3. ダイアログで OK を押す（自動売買許可は不要）                 |\n//|                                                                  |\n//|  【出力先】                                                      |\n//|  %USERPROFILE%\\MT4Export\\                                        |\n//|  mt4_report_<口座番号>.json                                      |\n//+------------------------------------------------------------------+\n#property copyright \"\"\n#property link      \"\"\n#property version   \"1.40\"\n#property strict\n#property description \"取引履歴を JSON へ自動エクスポートします。自動売買 OFF でも動作します。\"\n\n#import \"kernel32.dll\"\n   int  GetEnvironmentVariableW(string name, ushort &buf[], int bufSize);\n   int  CreateDirectoryW(string path, int sec);\n   int  CreateFileW(string path, uint access, uint share, int sec,\n                    uint disp, uint flags, int tmpl);\n   bool WriteFile(int hFile, uchar &buf[], uint toWrite, uint &written[], int overlapped);\n   bool CloseHandle(int hFile);\n   bool DeleteFileW(string path);\n#import\n\n#define GENERIC_WRITE         0x40000000\n#define GENERIC_READ          0x80000000\n#define CREATE_ALWAYS         2\n#define OPEN_EXISTING         3\n#define FILE_ATTRIBUTE_NORMAL 0x80\n#define FILE_SHARE_READ       1\n\ninput int    RefreshMinutes  = 5;            // 定期エクスポート間隔（分）\ninput string ExportSubFolder = \"MT4Export\";  // USERPROFILE 直下のサブフォルダ名\n\n// タイマー間隔（秒）: トリガーファイルをこの間隔でチェックする\n#define TIMER_SEC 5\n\nint      g_ExportTick        = 0; // TIMER_SEC 単位のカウンター\ndatetime g_LastTriggerExport = 0; // 直近のトリガー発火時刻（二重発火防止）\n\n//+------------------------------------------------------------------+\nint OnInit()\n{\n   EventSetTimer(TIMER_SEC);\n   ExportTrades();\n   return INIT_SUCCEEDED;\n}\n\nvoid OnDeinit(const int reason) { EventKillTimer(); }\n\nvoid OnTimer()\n{\n   // ブラウザからの即時エクスポート要求をチェック\n   bool triggered = CheckTrigger();\n\n   g_ExportTick++;\n   // triggered の場合、または定期インターバルに達した場合にエクスポート\n   if (triggered || g_ExportTick >= (RefreshMinutes * 60 / TIMER_SEC))\n   {\n      g_ExportTick = 0;\n      ExportTrades();\n   }\n}\n\n//+------------------------------------------------------------------+\n//|  トリガーファイル（_refresh.cmd）を確認する                      |\n//|  ブラウザが書き込むと即時エクスポートが発動する                  |\n//|  ファイルの削除はブラウザ側が行う（全インスタンス対応のため）    |\n//+------------------------------------------------------------------+\nbool CheckTrigger()\n{\n   string triggerPath = GetExportDir() + \"\\\\_refresh.cmd\";\n   int h = CreateFileW(triggerPath, GENERIC_READ, FILE_SHARE_READ, 0,\n                       OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, 0);\n   if (h == -1) return false;\n   CloseHandle(h);\n\n   // 30秒以内の二重発火を防ぐ\n   datetime now = TimeCurrent();\n   if (now - g_LastTriggerExport < 30) return false;\n   g_LastTriggerExport = now;\n   return true;\n}\n\n//+------------------------------------------------------------------+\nstring GetExportDir()\n{\n   ushort buf[260];\n   int len = GetEnvironmentVariableW(\"USERPROFILE\", buf, 260);\n   if (len <= 0) return \"\";\n   return ShortArrayToString(buf, 0, len) + \"\\\\\" + ExportSubFolder;\n}\n\nbool WriteStringToFile(string filepath, string content)\n{\n   uchar buf[];\n   int len = StringToCharArray(content, buf, 0, StringLen(content));\n   if (len <= 0) return false;\n\n   uint written[1];\n   int hFile = CreateFileW(filepath, GENERIC_WRITE, 0, 0, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, 0);\n   if (hFile == -1) return false;\n\n   bool ok = WriteFile(hFile, buf, (uint)len, written, 0);\n   CloseHandle(hFile);\n   return ok;\n}\n\n//+------------------------------------------------------------------+\n//|  取引履歴を JSON ファイルに書き出す                              |\n//+------------------------------------------------------------------+\nvoid ExportTrades()\n{\n   string exportDir = GetExportDir();\n   if (exportDir == \"\")\n   {\n      Print(\"[MT4Exporter] USERPROFILE が取得できません\");\n      return;\n   }\n\n   CreateDirectoryW(exportDir, 0);\n\n   string filepath = exportDir + \"\\\\mt4_report_\" + IntegerToString(AccountNumber()) + \".json\";\n\n   string json = \"{\\n\";\n   json += \"  \\\"account\\\": \"     + IntegerToString(AccountNumber())     + \",\\n\";\n   json += \"  \\\"name\\\": \\\"\"      + EscapeJson(AccountName())            + \"\\\",\\n\";\n   json += \"  \\\"server\\\": \\\"\"    + EscapeJson(AccountServer())          + \"\\\",\\n\";\n   json += \"  \\\"currency\\\": \\\"\"  + AccountCurrency()                    + \"\\\",\\n\";\n   json += \"  \\\"balance\\\": \"     + DoubleToString(AccountBalance(), 2)  + \",\\n\";\n   json += \"  \\\"equity\\\": \"      + DoubleToString(AccountEquity(),  2)  + \",\\n\";\n   json += \"  \\\"leverage\\\": \"    + IntegerToString(AccountLeverage())   + \",\\n\";\n   json += \"  \\\"exportTime\\\": \\\"\"+ TimeToISO(TimeCurrent())             + \"\\\",\\n\";\n   json += \"  \\\"trades\\\": [\\n\";\n\n   int total = OrdersHistoryTotal();\n   bool first = true;\n\n   for (int i = 0; i < total; i++)\n   {\n      if (!OrderSelect(i, SELECT_BY_POS, MODE_HISTORY)) continue;\n      if (OrderType() > OP_SELL) continue;\n\n      if (!first) json += \",\\n\";\n      first = false;\n\n      string typeStr    = (OrderType() == OP_BUY) ? \"buy\" : \"sell\";\n      double profit     = OrderProfit();\n      double swap       = OrderSwap();\n      double commission = OrderCommission();\n\n      json += \"    {\";\n      json += \"\\\"ticket\\\":\"      + IntegerToString(OrderTicket())             + \",\";\n      json += \"\\\"openTime\\\":\\\"\"  + TimeToISO(OrderOpenTime())                 + \"\\\",\";\n      json += \"\\\"closeTime\\\":\\\"\" + TimeToISO(OrderCloseTime())                + \"\\\",\";\n      json += \"\\\"type\\\":\\\"\"      + typeStr                                    + \"\\\",\";\n      json += \"\\\"size\\\":\"        + DoubleToString(OrderLots(),       2)       + \",\";\n      json += \"\\\"symbol\\\":\\\"\"    + OrderSymbol()                              + \"\\\",\";\n      json += \"\\\"openPrice\\\":\"   + DoubleToString(OrderOpenPrice(),  5)       + \",\";\n      json += \"\\\"closePrice\\\":\"  + DoubleToString(OrderClosePrice(), 5)       + \",\";\n      json += \"\\\"sl\\\":\"          + DoubleToString(OrderStopLoss(),   5)       + \",\";\n      json += \"\\\"tp\\\":\"          + DoubleToString(OrderTakeProfit(), 5)       + \",\";\n      json += \"\\\"commission\\\":\"  + DoubleToString(commission,        2)       + \",\";\n      json += \"\\\"swap\\\":\"        + DoubleToString(swap,              2)       + \",\";\n      json += \"\\\"profit\\\":\"      + DoubleToString(profit,            2)       + \",\";\n      json += \"\\\"netProfit\\\":\"   + DoubleToString(profit+swap+commission, 2)  + \",\";\n      json += \"\\\"comment\\\":\\\"\"   + EscapeJson(OrderComment())                 + \"\\\"\";\n      json += \"}\";\n   }\n\n   json += \"\\n  ]\\n}\\n\";\n\n   if (WriteStringToFile(filepath, json))\n      Print(\"[MT4Exporter] エクスポート完了: \", filepath, \"  (\", total, \" 件)\");\n   else\n      Print(\"[MT4Exporter] 書き込み失敗: \", filepath, \"  エラー: \", GetLastError());\n}\n\n//+------------------------------------------------------------------+\nstring EscapeJson(string s)\n{\n   StringReplace(s, \"\\\\\", \"\\\\\\\\\");\n   StringReplace(s, \"\\\"\", \"\\\\\\\"\");\n   StringReplace(s, \"\\n\", \"\\\\n\");\n   StringReplace(s, \"\\r\", \"\\\\r\");\n   StringReplace(s, \"\\t\", \"\\\\t\");\n   return s;\n}\n\nstring TimeToISO(datetime t)\n{\n   if (t == 0) return \"\";\n   return TimeToString(t, TIME_DATE | TIME_SECONDS);\n}\n"
